// src/daemon/watchers/branch-discovery.ts
var BRANCH_PULLS_ETAG_SCOPE = "branch.pulls.author-gate.v1";
var etagKey = (repo, branch) => `${repo}#${branch}`;

class BranchDiscoveryWatcher {
	store;
	github;
	worktreeBindings;
	logger = createLogger("daemon.branch-discovery");
	constructor(
		store,
		github,
		worktreeBindings = new WorktreeBindingRegistry(store),
	) {
		this.store = store;
		this.github = github;
		this.worktreeBindings = worktreeBindings;
	}
	async tick(now = Date.now()) {
		const targetsByBranch = new Map();
		for (const target of this.store.listActiveWorktreeBranchTargets(now)) {
			const key = etagKey(target.repo, target.branch);
			const targets = targetsByBranch.get(key);
			if (targets) targets.push(target);
			else targetsByBranch.set(key, [target]);
		}
		if (targetsByBranch.size === 0) return;
		let viewerLogin;
		try {
			viewerLogin = await this.github.getViewerLogin();
		} catch (error) {
			this.store.suspendAutomaticSubscriptions(now);
			this.logger.warn(
				"unable to identify authenticated GitHub user; skipping automatic PR discovery",
				{
					error: error instanceof Error ? error.message : String(error),
				},
			);
			return;
		}
		if (!viewerLogin) {
			this.store.suspendAutomaticSubscriptions(now);
			this.logger.warn(
				"authenticated GitHub user has no login; skipping automatic PR discovery",
			);
			return;
		}
		for (const targets of targetsByBranch.values()) {
			const target = targets[0];
			try {
				const cachedEtag = this.store.getEtag(
					BRANCH_PULLS_ETAG_SCOPE,
					etagKey(target.repo, target.branch),
				);
				const result = await this.github.findOpenPullRequestForBranch(
					target.repo,
					target.branch,
					{
						etag: cachedEtag,
					},
				);
				if (result.kind === "not_modified") {
					if (result.etag && result.etag !== cachedEtag) {
						this.store.saveEtag(
							BRANCH_PULLS_ETAG_SCOPE,
							etagKey(target.repo, target.branch),
							result.etag,
							now,
						);
					}
					continue;
				}
				if (result.etag !== null) {
					this.store.saveEtag(
						BRANCH_PULLS_ETAG_SCOPE,
						etagKey(target.repo, target.branch),
						result.etag,
						now,
					);
				}
				const pr = result.pr;
				if (pr && pr.authorLogin?.toLowerCase() !== viewerLogin.toLowerCase()) {
					this.logger.info(
						"automatic PR watch disabled for a foreign-authored PR",
						{
							repo: target.repo,
							branch: target.branch,
							prNumber: pr.number,
							authorLogin: pr.authorLogin,
							viewerLogin,
						},
					);
					for (const binding of targets) {
						if (binding.git_dir !== "") {
							this.worktreeBindings.pullRequestNotOwned(
								binding.session_id,
								{ repo: binding.repo, prNumber: pr.number },
								now,
							);
						} else {
							this.store.rejectAutomaticPullRequest(
								binding.session_id,
								binding.repo,
								pr.number,
								now,
							);
						}
					}
					continue;
				}
				if (pr && target.pr_number !== null && pr.number !== target.pr_number) {
					const previousState = this.store.getSnapshot(
						target.repo,
						target.pr_number,
					)?.core.state;
					if (previousState !== "MERGED" && previousState !== "CLOSED") {
						this.logger.info(
							"deferring branch reassociation until prior PR reaches a terminal state",
							{
								repo: target.repo,
								branch: target.branch,
								previousPrNumber: target.pr_number,
								nextPrNumber: pr.number,
								previousState: previousState ?? null,
							},
						);
						continue;
					}
				}
				this.store.recordBranchAssociation(
					target.repo,
					target.branch,
					pr?.number ?? target.pr_number,
					now,
				);
				if (!pr) {
					for (const binding of targets) {
						if (binding.git_dir !== "") {
							this.worktreeBindings.pullRequestNotFound(
								binding.session_id,
								now,
							);
						}
					}
					continue;
				}
				for (const binding of targets) {
					if (binding.git_dir !== "") {
						this.worktreeBindings.pullRequestFound(
							binding.session_id,
							{ repo: binding.repo, prNumber: pr.number },
							now,
						);
					}
				}
				this.store.insertEvents(
					target.repo,
					pr.number,
					[
						{
							dedupeKey: `pr.discovered:${target.repo}:${target.branch}:${pr.number}`,
							kind: "pr.discovered",
							priority: "medium",
							summary: `Discovered open PR ${target.repo}#${pr.number}: ${pr.title}`,
							referenceLink: pr.url,
							payload: {
								repo: target.repo,
								branch: target.branch,
								prNumber: pr.number,
								title: pr.title,
								url: pr.url,
							},
						},
					],
					now,
				);
			} catch (error) {
				this.logger.warn("branch discovery failed", {
					repo: target.repo,
					branch: target.branch,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}
	}
}

